def award_point(state, side):
    if side != "left" and side != "right":
        raise ValueError("Unknown side")
    state[side] += 1
    if state[side] >= state["target"]:
        return side
    return None

match = {"left": 2, "right": 1, "target": 3}
winner = award_point(match, "left")
print(match)
print("Winner:", winner)
